window.CGU_DATA={"version":"1.0.0","generated":"2026-10-13","exam":"2026-12-13","registerEnd":"2026-11-04","questions":[{"id":"CGU-A-001","p":"P3","topic":"Redes e sistemas","answer":"E","text":"O DNS é responsável por distribuir endereços IP automaticamente às estações.","explanation":"A atribuição dinâmica de parâmetros IP é uma função usual do DHCP; DNS resolve nomes.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-002","p":"P3","topic":"Redes e sistemas","answer":"C","text":"O TCP implementa mecanismos de confirmação e retransmissão, ausentes como garantias nativas no UDP.","explanation":"A confiabilidade faz parte do TCP; aplicações podem implementá-la sobre UDP.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-003","p":"P3","topic":"Redes e sistemas","answer":"E","text":"Um switch Ethernet de camada 2 encaminha quadros consultando principalmente o IP de destino.","explanation":"A comutação de camada 2 usa endereços MAC; roteamento usa IP.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-004","p":"P3","topic":"Redes e sistemas","answer":"C","text":"Um registro AAAA do DNS pode associar um nome a um endereço IPv6.","explanation":"A aponta para IPv4; AAAA para IPv6.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-005","p":"P3","topic":"Redes e sistemas","answer":"C","text":"Um endereço IPv6 possui 128 bits, ao passo que o IPv4 possui 32 bits.","explanation":"Os comprimentos de endereços são distintos.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-006","p":"P3","topic":"Redes e sistemas","answer":"E","text":"A adoção de NAT elimina a necessidade de políticas de firewall.","explanation":"Tradução de endereços e filtragem de tráfego têm funções diferentes.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-007","p":"P3","topic":"Redes e sistemas","answer":"C","text":"VLANs podem separar domínios de broadcast de camada 2.","explanation":"A comunicação entre VLANs geralmente exige roteamento.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-008","p":"P3","topic":"Redes e sistemas","answer":"E","text":"Uma VPN IPsec assegura automaticamente a segurança dos sistemas nas duas extremidades do túnel.","explanation":"Protege aspectos do tráfego; não corrige vulnerabilidades dos endpoints.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-009","p":"P3","topic":"Redes e sistemas","answer":"C","text":"Jitter mede a variação do atraso entre pacotes.","explanation":"Latência é atraso; jitter é sua variação.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-010","p":"P3","topic":"Redes e sistemas","answer":"E","text":"Uma rota de menor latência sempre possui maior largura de banda disponível.","explanation":"Atraso e capacidade de transmissão são grandezas diferentes.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-011","p":"P3","topic":"Redes e sistemas","answer":"C","text":"O BGP utiliza atributos e políticas para seleção e anúncio de rotas entre sistemas autônomos.","explanation":"Não é apenas a escolha do caminho com menos saltos.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-012","p":"P3","topic":"Redes e sistemas","answer":"E","text":"O OSPF é um protocolo de roteamento interdomínios baseado em path-vector.","explanation":"OSPF é um protocolo link-state, tipicamente intradomínio.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-013","p":"P3","topic":"Redes e sistemas","answer":"C","text":"O protocolo DHCP pode disponibilizar gateway padrão e servidores DNS além do endereço IP.","explanation":"DHCP fornece parâmetros diversos da configuração IP.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-014","p":"P3","topic":"Redes e sistemas","answer":"E","text":"A existência de um balanceador de carga elimina qualquer ponto único de falha do sistema.","explanation":"O balanceador e outros componentes também precisam de resiliência.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-015","p":"P3","topic":"Redes e sistemas","answer":"C","text":"O uso de QoS pode priorizar determinadas classes de tráfego em situações de congestionamento.","explanation":"Filas e políticas podem diferenciar tratamento de pacotes.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-016","p":"P3","topic":"Redes e sistemas","answer":"E","text":"O serviço systemd em Linux é responsável exclusivamente por armazenar arquivos de log.","explanation":"É gerenciador de sistema e serviços; a coleta de logs pode usar journald.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-017","p":"P3","topic":"Redes e sistemas","answer":"C","text":"Uma ACL pode expressar permissões de acesso mais granulares que as permissões tradicionais de dono, grupo e outros.","explanation":"ACLs estendem mecanismos de autorização em sistemas de arquivos.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-018","p":"P3","topic":"Redes e sistemas","answer":"E","text":"LDAP e Active Directory são rigorosamente sinônimos.","explanation":"LDAP é protocolo; Active Directory é serviço de diretório que pode usar LDAP.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-019","p":"P3","topic":"Redes e sistemas","answer":"C","text":"Storage de objetos costuma oferecer acesso por API e identificação por objeto/chave.","explanation":"Diferencia-se do acesso a blocos e a sistemas de arquivos tradicionais.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-020","p":"P3","topic":"Redes e sistemas","answer":"E","text":"RAID 1 oferece tolerância a falhas mediante distribuição de paridade entre três ou mais discos.","explanation":"RAID 1 espelha dados; paridade distribuída caracteriza outros níveis como RAID 5.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-021","p":"P3","topic":"Redes e sistemas","answer":"C","text":"IOPS mede quantidade de operações de entrada/saída por segundo.","explanation":"Não é sinônimo de throughput em bytes/s.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-022","p":"P3","topic":"Redes e sistemas","answer":"E","text":"O uso de cache garante, por si só, consistência forte entre todas as réplicas de um banco.","explanation":"Consistência exige mecanismos próprios de coordenação/invalidação.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-023","p":"P3","topic":"Redes e sistemas","answer":"C","text":"O log de transações pode auxiliar recuperação e garantia de durabilidade de banco de dados.","explanation":"WAL registra mudanças necessárias a recuperação.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-024","p":"P3","topic":"Redes e sistemas","answer":"E","text":"A replicação assíncrona impede qualquer perda de dados caso o primário falhe abruptamente.","explanation":"Pode haver operações ainda não propagadas à réplica.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-025","p":"P3","topic":"Redes e sistemas","answer":"C","text":"Índices B-tree favorecem consultas por intervalo e ordenação em muitos SGBDs.","explanation":"Estruturas ordenadas oferecem vantagens em buscas por faixa.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-026","p":"P3","topic":"Redes e sistemas","answer":"E","text":"Uma transação ACID garante disponibilidade contínua durante toda partição de rede.","explanation":"ACID trata propriedades de transações, não elimina limitações de sistemas distribuídos.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-027","p":"P3","topic":"Redes e sistemas","answer":"C","text":"A cláusula GROUP BY pode ser combinada com funções agregadoras em SQL.","explanation":"Agrupa linhas para cálculo de agregações.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-028","p":"P3","topic":"Redes e sistemas","answer":"E","text":"HAVING e WHERE são sempre intercambiáveis sem alterar o resultado de consultas SQL.","explanation":"WHERE filtra linhas; HAVING filtra grupos depois do agrupamento.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-029","p":"P3","topic":"Redes e sistemas","answer":"C","text":"A replicação síncrona pode aumentar a latência de escrita quando é necessário confirmar escrita remota.","explanation":"Há compromisso entre confirmação distribuída e desempenho.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-030","p":"P3","topic":"Redes e sistemas","answer":"E","text":"Um backup nunca precisa ser testado se o software relata execução bem-sucedida.","explanation":"Testes de restauração verificam recuperabilidade real.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-031","p":"P3","topic":"Nuvem e automação","answer":"C","text":"Em IaaS, o cliente normalmente administra mais componentes do ambiente do que em SaaS.","explanation":"A distribuição exata das responsabilidades varia por serviço e provedor.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-032","p":"P3","topic":"Nuvem e automação","answer":"E","text":"No modelo SaaS, o provedor assume automaticamente todas as obrigações de proteção dos dados do cliente.","explanation":"O cliente mantém obrigações como gestão de acesso, classificação e uso adequado.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-033","p":"P3","topic":"Nuvem e automação","answer":"C","text":"Elasticidade envolve ajuste de recursos conforme variação de demanda.","explanation":"Escalabilidade é capacidade de crescer; elasticidade enfatiza ajuste dinâmico.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-034","p":"P3","topic":"Nuvem e automação","answer":"E","text":"Escalabilidade vertical significa adicionar novas instâncias do serviço.","explanation":"Vertical altera recursos da instância; horizontal aumenta instâncias.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-035","p":"P3","topic":"Nuvem e automação","answer":"C","text":"Contêineres compartilham o kernel do sistema hospedeiro, diferentemente da virtualização completa por máquina virtual.","explanation":"Há diferentes mecanismos de isolamento e empacotamento.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-036","p":"P3","topic":"Nuvem e automação","answer":"E","text":"Uma imagem de contêiner imutável implica que todo dado escrito em execução persiste após a remoção do contêiner.","explanation":"Persistência demanda volumes ou outros mecanismos externos.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-037","p":"P3","topic":"Nuvem e automação","answer":"C","text":"Uma infraestrutura declarativa descreve o estado desejado, e não necessariamente cada passo para alcançá-lo.","explanation":"IaC declarativa facilita reconciliação do estado.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-038","p":"P3","topic":"Nuvem e automação","answer":"E","text":"Idempotência significa que uma automação obrigatoriamente produz efeitos diferentes a cada execução.","explanation":"Operações idempotentes repetidas tendem a preservar o mesmo estado final.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-039","p":"P3","topic":"Nuvem e automação","answer":"C","text":"O versionamento de IaC auxilia auditoria, revisão e rastreabilidade de mudanças.","explanation":"Código e revisões documentam evolução do ambiente.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-040","p":"P3","topic":"Nuvem e automação","answer":"E","text":"Uma pipeline de CI/CD torna desnecessária a gestão segura de segredos e credenciais.","explanation":"Credenciais precisam de proteção e menor privilégio.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-041","p":"P3","topic":"Nuvem e automação","answer":"C","text":"Rehost normalmente significa migrar a carga com poucas alterações de arquitetura.","explanation":"Refactor envolve mudanças arquiteturais maiores.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-042","p":"P3","topic":"Nuvem e automação","answer":"E","text":"Serverless significa ausência de servidores físicos por trás da aplicação.","explanation":"Infraestrutura continua existindo, mas sua gestão é abstraída do consumidor.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-043","p":"P3","topic":"Nuvem e automação","answer":"C","text":"Um balanceador com health checks pode deixar de direcionar tráfego a instâncias consideradas indisponíveis.","explanation":"Isso não substitui todos os controles de continuidade.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-044","p":"P3","topic":"Nuvem e automação","answer":"E","text":"O padrão publish-subscribe exige que produtor e consumidor mantenham conexão direta entre si.","explanation":"Um intermediário desacopla publicação e consumo.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-045","p":"P3","topic":"Nuvem e automação","answer":"C","text":"A adoção de serviços gerenciados pode reduzir carga operacional, mas introduz dependências contratuais e tecnológicas.","explanation":"Trade-offs incluem lock-in, custo, segurança e portabilidade.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-046","p":"P3","topic":"Nuvem e automação","answer":"E","text":"A criação de múltiplas instâncias na mesma zona de disponibilidade elimina qualquer risco de indisponibilidade zonal.","explanation":"Todas podem ser afetadas por falha da mesma zona.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-047","p":"P3","topic":"Nuvem e automação","answer":"C","text":"Em migração de dados, é prudente definir validação de integridade e possibilidade de reversão antes da mudança.","explanation":"Controles reduzem risco de perda e de interrupção.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-048","p":"P3","topic":"Nuvem e automação","answer":"E","text":"O uso de containers elimina a necessidade de atualizar bibliotecas e corrigir vulnerabilidades nas imagens.","explanation":"Imagens também exigem gestão de vulnerabilidades e atualização.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-049","p":"P3","topic":"Nuvem e automação","answer":"C","text":"Em FinOps, a visibilidade de consumo e o rateio de custos auxiliam decisões de otimização da nuvem.","explanation":"Custos devem ser relacionados ao uso e ao valor gerado.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-050","p":"P3","topic":"Nuvem e automação","answer":"E","text":"Uma VPC pública permite, sem qualquer regra de segurança, acesso irrestrito a todos os recursos internos.","explanation":"Regras de roteamento, ACLs e security groups controlam conectividade.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-051","p":"P3","topic":"Segurança e continuidade","answer":"E","text":"Autenticação é o processo que define as operações permitidas após a identidade ter sido verificada.","explanation":"Autenticação verifica identidade; autorização determina permissões.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-052","p":"P3","topic":"Segurança e continuidade","answer":"C","text":"MFA pode exigir fatores de categorias distintas para fortalecer a autenticação.","explanation":"Duas senhas da mesma categoria não significam necessariamente dois fatores.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-053","p":"P3","topic":"Segurança e continuidade","answer":"E","text":"Em Zero Trust, todos os dispositivos da rede interna são considerados confiáveis por padrão.","explanation":"Zero Trust enfatiza verificação explícita e privilégio mínimo.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-054","p":"P3","topic":"Segurança e continuidade","answer":"C","text":"WAF atua sobre tráfego HTTP/HTTPS e pode reduzir ataques a aplicações web.","explanation":"Não substitui controles de rede ou segurança do código.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-055","p":"P3","topic":"Segurança e continuidade","answer":"E","text":"O IDS sempre bloqueia automaticamente o tráfego malicioso identificado.","explanation":"IDS detecta/alerta; IPS pode prevenir/bloquear.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-056","p":"P3","topic":"Segurança e continuidade","answer":"C","text":"A microsegmentação pode restringir comunicação lateral entre cargas de trabalho.","explanation":"Exige políticas efetivas e observabilidade.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-057","p":"P3","topic":"Segurança e continuidade","answer":"E","text":"OAuth 2.0 é, por si só, um protocolo completo de autenticação de identidade de usuário final.","explanation":"É um framework de autorização; OIDC agrega camada de identidade.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-058","p":"P3","topic":"Segurança e continuidade","answer":"C","text":"O princípio do menor privilégio recomenda conceder somente as permissões necessárias.","explanation":"Reduz consequências de abuso ou comprometimento.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-059","p":"P3","topic":"Segurança e continuidade","answer":"E","text":"Criptografia simétrica utiliza obrigatoriamente um par distinto de chaves pública e privada.","explanation":"Par de chaves caracteriza criptografia assimétrica.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-060","p":"P3","topic":"Segurança e continuidade","answer":"C","text":"Uma assinatura digital bem implementada pode oferecer verificação de integridade e autenticidade.","explanation":"Não fornece sigilo do conteúdo por si só.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-061","p":"P3","topic":"Segurança e continuidade","answer":"E","text":"Um certificado digital válido garante que o software do titular não contém vulnerabilidades.","explanation":"Certificados não asseguram qualidade/segurança global da aplicação.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-062","p":"P3","topic":"Segurança e continuidade","answer":"C","text":"Hash criptográfico pode ajudar na verificação de integridade de evidências digitais.","explanation":"O contexto e a cadeia de custódia continuam importantes.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-063","p":"P3","topic":"Segurança e continuidade","answer":"E","text":"O uso de um SIEM torna dispensável a definição de procedimentos de resposta a incidentes.","explanation":"Correlação de eventos não substitui processo, equipe e decisão.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-064","p":"P3","topic":"Segurança e continuidade","answer":"C","text":"EDR concentra-se em detecção e resposta em endpoints, enquanto SIEM correlaciona eventos de diferentes fontes.","explanation":"Há sobreposição possível, mas objetivos e arquiteturas são distintos.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-065","p":"P3","topic":"Segurança e continuidade","answer":"E","text":"A anonimização e a pseudonimização retiram sempre e integralmente os dados do alcance da LGPD.","explanation":"Dados pseudonimizados podem continuar sendo dados pessoais.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-066","p":"P3","topic":"Segurança e continuidade","answer":"C","text":"RTO expressa o tempo-alvo máximo aceitável para restaurar serviço após interrupção.","explanation":"RPO se refere à perda potencial de dados expressa em tempo.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-067","p":"P3","topic":"Segurança e continuidade","answer":"E","text":"RPO representa o período máximo tolerável de indisponibilidade do serviço.","explanation":"Este é o papel do RTO.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-068","p":"P3","topic":"Segurança e continuidade","answer":"C","text":"Cópias imutáveis e testes de restauração são controles úteis na proteção contra ransomware.","explanation":"Backup sem recuperação validada pode falhar em incidente real.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-069","p":"P3","topic":"Segurança e continuidade","answer":"E","text":"Replicar dados continuamente equivale a manter backup histórico protegido contra exclusão lógica.","explanation":"Replicação pode propagar exclusões e corrupções.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-070","p":"P3","topic":"Segurança e continuidade","answer":"C","text":"A análise de impacto no negócio ajuda a definir prioridades e requisitos de continuidade.","explanation":"BIA identifica consequências e criticidade da interrupção.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-071","p":"P3","topic":"Segurança e continuidade","answer":"E","text":"Uma falha de segurança deixa de ser incidente assim que a equipe consegue conter sua propagação.","explanation":"Contenção é apenas uma etapa; erradicação e recuperação podem ser necessárias.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-072","p":"P3","topic":"Segurança e continuidade","answer":"C","text":"A preservação de evidências digitais requer documentação da coleta e do manuseio.","explanation":"Rastreabilidade da cadeia de custódia reduz questionamentos.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-073","p":"P3","topic":"Governança, operação e contratos","answer":"C","text":"Traces distribuídos ajudam a correlacionar uma requisição ao longo de múltiplos serviços.","explanation":"Complementam logs e métricas.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-074","p":"P3","topic":"Governança, operação e contratos","answer":"E","text":"SLI é a meta de confiabilidade negociada contratualmente com o cliente.","explanation":"SLI é indicador; SLO é objetivo; SLA é acordo.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-075","p":"P3","topic":"Governança, operação e contratos","answer":"C","text":"Um orçamento de erro pode ajudar a equilibrar rapidez de mudança com requisitos de confiabilidade.","explanation":"Prática de SRE considera erro permitido pelo SLO.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-076","p":"P3","topic":"Governança, operação e contratos","answer":"E","text":"Na ITIL, gerenciamento de incidentes busca prioritariamente identificar todas as causas raízes e impedir recorrência.","explanation":"Restaurar serviço rapidamente é foco de incidente; causa raiz costuma ser foco de problema.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-077","p":"P3","topic":"Governança, operação e contratos","answer":"C","text":"Uma mudança padrão pode ser previamente autorizada se suas condições e baixo risco forem conhecidos.","explanation":"Diferencia-se de mudanças normais e emergenciais.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-078","p":"P3","topic":"Governança, operação e contratos","answer":"E","text":"A CMDB mantém apenas inventário financeiro de hardware, sem relações entre itens de configuração.","explanation":"CMDB pode representar itens e relações relevantes à entrega do serviço.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-079","p":"P3","topic":"Governança, operação e contratos","answer":"C","text":"O catálogo de erros conhecidos pode acelerar contornos e diagnóstico de incidentes recorrentes.","explanation":"Gestão de problemas armazena conhecimento.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-080","p":"P3","topic":"Governança, operação e contratos","answer":"E","text":"Scrum determina que toda equipe deve trabalhar com fluxo contínuo sem iterações de tempo fixo.","explanation":"Scrum opera com Sprints; Kanban enfatiza fluxo.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-081","p":"P3","topic":"Governança, operação e contratos","answer":"C","text":"Segregação de funções pode reduzir risco de fraude ao distribuir atividades incompatíveis.","explanation":"Complementa controles de acesso e revisão.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-082","p":"P3","topic":"Governança, operação e contratos","answer":"E","text":"A existência de SLA dispensa critérios de aceite, medição de desempenho e fiscalização de contratos.","explanation":"SLA precisa de mecanismos de acompanhamento e evidências.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-083","p":"P3","topic":"Governança, operação e contratos","answer":"C","text":"O ETP deve contribuir para avaliar alternativas e fundamentar a solução de contratação.","explanation":"ETP precede, em geral, detalhamento do termo de referência.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-084","p":"P3","topic":"Governança, operação e contratos","answer":"E","text":"Um termo de referência e um estudo técnico preliminar têm exatamente a mesma finalidade.","explanation":"ETP fundamenta necessidade e solução; TR especifica condições da contratação.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-085","p":"P3","topic":"Governança, operação e contratos","answer":"C","text":"Um plano de saída contratual pode reduzir dependência de fornecedor de serviços de TI.","explanation":"Portabilidade e continuidade são preocupações relevantes.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-086","p":"P3","topic":"Governança, operação e contratos","answer":"E","text":"PDTIC se restringe à compra de computadores e não pode alinhar-se ao planejamento estratégico institucional.","explanation":"Planejamento de TIC visa necessidades e objetivos organizacionais.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-087","p":"P3","topic":"Governança, operação e contratos","answer":"C","text":"A indisponibilidade de uma dependência externa pode comprometer o SLO mesmo que a aplicação principal permaneça íntegra.","explanation":"SLO é percebido na entrega de serviço, não isoladamente no componente.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-088","p":"P3","topic":"Governança, operação e contratos","answer":"E","text":"Observabilidade e monitoramento são conceitos idênticos que dispensam investigação de eventos não antecipados.","explanation":"Observabilidade busca inferir estados internos também em cenários não previamente previstos.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"intermediário"},{"id":"CGU-A-089","p":"P2","topic":"Governança, integridade e controle","answer":"C","text":"Risco residual é o nível de risco remanescente após a consideração dos controles implementados.","explanation":"Diferencia-se do risco inerente, anterior aos controles.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-090","p":"P2","topic":"Governança, integridade e controle","answer":"E","text":"Apetite a risco corresponde necessariamente ao risco já ocorrido e materializado.","explanation":"Apetite expressa nível/tipo de risco que a organização aceita assumir.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-091","p":"P2","topic":"Governança, integridade e controle","answer":"C","text":"Controle preventivo busca evitar ocorrência; detectivo identifica ocorrência; corretivo trata efeitos ou falhas.","explanation":"Os objetivos dos controles são distintos.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-092","p":"P2","topic":"Governança, integridade e controle","answer":"E","text":"As três linhas atribuem à auditoria interna a responsabilidade principal por operar os controles da gestão.","explanation":"Gestão opera controles; auditoria fornece avaliação independente.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-093","p":"P2","topic":"Governança, integridade e controle","answer":"C","text":"Governança define diretrizes e supervisiona resultados, enquanto gestão executa ações para atingir objetivos.","explanation":"São funções relacionadas, mas distintas.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-094","p":"P2","topic":"Governança, integridade e controle","answer":"E","text":"Transparência ativa depende sempre de pedido individual do cidadão.","explanation":"Divulgação proativa é ativa; resposta ao pedido é passiva.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-095","p":"P2","topic":"Governança, integridade e controle","answer":"C","text":"Dados pseudonimizados podem continuar sendo dados pessoais quando a reidentificação permanece possível.","explanation":"Pseudonimização difere de anonimização efetiva.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-096","p":"P2","topic":"Governança, integridade e controle","answer":"E","text":"O controle externo da União é exercido exclusivamente pela CGU.","explanation":"Congresso Nacional exerce controle externo com auxílio do TCU.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-097","p":"P2","topic":"Governança, integridade e controle","answer":"C","text":"A avaliação de um programa de integridade deve considerar efetividade prática, não apenas documentos produzidos.","explanation":"Compliance formal não garante prevenção/detecção real.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-098","p":"P2","topic":"Governança, integridade e controle","answer":"E","text":"Uma denúncia isolada constitui necessariamente prova suficiente de irregularidade.","explanation":"Denúncias são insumos para análise e apuração, não conclusão automática.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-099","p":"P2","topic":"Governança, integridade e controle","answer":"C","text":"Um achado de auditoria pode relacionar condição, critério, causa e efeito.","explanation":"Elementos estruturam análise e comunicação do achado.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-100","p":"P2","topic":"Governança, integridade e controle","answer":"E","text":"Evidência de auditoria adequada dispensa avaliação de suficiência.","explanation":"Suficiência e adequação são atributos distintos.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-101","p":"P2","topic":"Governança, integridade e controle","answer":"C","text":"A triangulação de fontes pode ajudar a avaliar confiabilidade de evidências.","explanation":"Confronta registros, documentos e outras informações.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-102","p":"P2","topic":"Governança, integridade e controle","answer":"E","text":"Correlação estatística, por si só, demonstra relação de causa e efeito.","explanation":"Pode haver variáveis de confusão e outras explicações.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-103","p":"P2","topic":"Governança, integridade e controle","answer":"C","text":"Monitoramento de recomendações deve distinguir adoção formal de efetiva redução de riscos.","explanation":"Implementação documental não garante benefício real.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-104","p":"P2","topic":"Governança, integridade e controle","answer":"E","text":"A ouvidoria exerce necessariamente função sancionatória sobre todo denunciado.","explanation":"Ouvidoria acolhe e trata manifestações; responsabilização segue procedimentos próprios.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-105","p":"P2","topic":"Governança, integridade e controle","answer":"C","text":"O compartilhamento de dados pela administração pública requer finalidade legítima e salvaguardas apropriadas.","explanation":"Transparência e proteção de dados devem ser conciliadas.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-106","p":"P2","topic":"Governança, integridade e controle","answer":"E","text":"Uma política pública somente pode ser avaliada após sua conclusão integral.","explanation":"Monitoramento e avaliações de processo podem ocorrer durante execução.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-107","p":"P2","topic":"Governança, integridade e controle","answer":"C","text":"Cadeia de custódia documentada fortalece rastreabilidade e confiabilidade da evidência.","explanation":"Registros de coleta, guarda e manuseio são relevantes.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-108","p":"P2","topic":"Governança, integridade e controle","answer":"E","text":"Um modelo de IA com elevado desempenho médio está automaticamente livre de vieses discriminatórios.","explanation":"É preciso analisar grupos, dados e efeitos.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-109","p":"P2","topic":"Governança, integridade e controle","answer":"C","text":"Um falso negativo pode representar risco elevado em ferramenta que busca detectar fraude.","explanation":"A classificação incorreta de fraude como regular pode ocultar casos.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-110","p":"P2","topic":"Governança, integridade e controle","answer":"E","text":"A indicação de um dado como 'aberto' elimina restrições relativas a dados pessoais.","explanation":"Abertura de dados não afasta regras de privacidade.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-111","p":"P2","topic":"Governança, integridade e controle","answer":"C","text":"Uma auditoria interna pode prestar serviços de avaliação e consultoria sem assumir decisões executivas da gestão.","explanation":"Independência e objetividade devem ser preservadas.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-112","p":"P2","topic":"Governança, integridade e controle","answer":"E","text":"O princípio da segregação de funções recomenda que a mesma pessoa solicite, autorize, execute e ateste integralmente a despesa.","explanation":"Distribuir funções incompatíveis reduz riscos.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-113","p":"P2","topic":"Governança, integridade e controle","answer":"C","text":"A baixa quantidade de denúncias pode resultar de subnotificação, e não necessariamente de poucos problemas.","explanation":"Indicadores de detecção não medem diretamente prevalência.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-114","p":"P2","topic":"Governança, integridade e controle","answer":"E","text":"Accountability significa apenas disponibilizar dados, sem necessidade de justificar decisões ou aceitar responsabilização.","explanation":"Inclui prestação de contas, justificativa e responsabilização.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-115","p":"P2","topic":"Governança, integridade e controle","answer":"C","text":"A ética pública exige lidar com conflitos entre interesse privado e função pública.","explanation":"Prevenção de conflito de interesses integra integridade.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-116","p":"P2","topic":"Governança, integridade e controle","answer":"E","text":"A detecção automatizada de anomalias por IA substitui integralmente a análise humana e as garantias processuais.","explanation":"Decisões relevantes exigem controles, supervisão e garantia de direitos.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-117","p":"P1","topic":"Estado, políticas públicas e sociedade","answer":"C","text":"A administração pública integra a organização do Estado, mas não se confunde com o governo.","explanation":"Governo exerce direção política; administração executa funções administrativas.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-118","p":"P1","topic":"Estado, políticas públicas e sociedade","answer":"E","text":"Em federação, os entes subnacionais não possuem qualquer autonomia constitucional.","explanation":"Autonomia federativa é característica essencial.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-119","p":"P1","topic":"Estado, políticas públicas e sociedade","answer":"C","text":"O modelo de freios e contrapesos admite mecanismos de controle recíproco entre Poderes.","explanation":"Separação de Poderes não significa isolamento absoluto.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-120","p":"P1","topic":"Estado, políticas públicas e sociedade","answer":"E","text":"Eficiência administrativa autoriza afastar o devido processo legal sempre que houver ganho de produtividade.","explanation":"Eficiência deve ser harmonizada com garantias e legalidade.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-121","p":"P1","topic":"Estado, políticas públicas e sociedade","answer":"C","text":"A implementação de políticas públicas pode ser influenciada pela atuação discricionária de burocratas de nível de rua.","explanation":"A execução cotidiana influencia entrega de serviços.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-122","p":"P1","topic":"Estado, políticas públicas e sociedade","answer":"E","text":"Transição demográfica significa, necessariamente, crescimento contínuo da proporção de jovens.","explanation":"Pode envolver envelhecimento e mudanças na natalidade/mortalidade.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-123","p":"P1","topic":"Estado, políticas públicas e sociedade","answer":"C","text":"Interseccionalidade analisa a interação de diferentes eixos de desigualdade.","explanation":"A análise não se limita a um fator isolado.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-124","p":"P1","topic":"Estado, políticas públicas e sociedade","answer":"E","text":"A corrupção se identifica automaticamente com toda falha administrativa, ainda que sem desvio de conduta.","explanation":"Falha de gestão e prática corrupta não são conceitos equivalentes.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-125","p":"P1","topic":"Estado, políticas públicas e sociedade","answer":"C","text":"A relação principal-agente pode envolver assimetria de informações e incentivos conflitantes.","explanation":"É uma lente explicativa de problemas de controle.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-126","p":"P1","topic":"Estado, políticas públicas e sociedade","answer":"E","text":"Participação social elimina a necessidade de representação política em qualquer democracia.","explanation":"Mecanismos podem ser complementares.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-127","p":"P1","topic":"Estado, políticas públicas e sociedade","answer":"C","text":"O ciclo de políticas públicas pode compreender formulação, implementação, monitoramento e avaliação.","explanation":"O ciclo é modelo analítico, não sequência sempre rígida.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-128","p":"P1","topic":"Estado, políticas públicas e sociedade","answer":"E","text":"Todo indicador de resultado é equivalente a indicador de insumo.","explanation":"Insumos, processos, produtos e resultados têm funções distintas.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-129","p":"P1","topic":"Estado, políticas públicas e sociedade","answer":"C","text":"A descentralização e a desconcentração administrativa têm significados distintos.","explanation":"Descentralização transfere execução a outra pessoa; desconcentração distribui competências internamente.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-130","p":"P1","topic":"Estado, políticas públicas e sociedade","answer":"E","text":"Autarquia é pessoa jurídica de direito privado integrante da administração direta.","explanation":"Autarquia integra administração indireta e é pessoa jurídica de direito público.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-131","p":"P1","topic":"Estado, políticas públicas e sociedade","answer":"C","text":"Transparência, integridade e prestação de contas contribuem para legitimidade da administração.","explanation":"São dimensões de governança e valor público.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-132","p":"P1","topic":"Estado, políticas públicas e sociedade","answer":"E","text":"Toda desigualdade observada em indicador social demonstra, isoladamente, discriminação jurídica intencional.","explanation":"Causas podem ser complexas; inferência exige evidências.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-133","p":"P1","topic":"Estado, políticas públicas e sociedade","answer":"C","text":"A avaliação de impacto busca estimar mudanças atribuíveis à intervenção pública, conforme desenho metodológico.","explanation":"Precisa distinguir resultados de tendências e fatores externos.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-134","p":"P1","topic":"Estado, políticas públicas e sociedade","answer":"E","text":"Legalidade e legitimidade são sinônimos perfeitos em qualquer discussão sobre ação estatal.","explanation":"Atuação legal pode suscitar questões de legitimidade política/social.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-135","p":"P1","topic":"Estado, políticas públicas e sociedade","answer":"C","text":"A ideia de valor público envolve efeitos relevantes para cidadãos e sociedade.","explanation":"Não se reduz a economia financeira interna.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"},{"id":"CGU-A-136","p":"P1","topic":"Estado, políticas públicas e sociedade","answer":"E","text":"Políticas universalistas necessariamente distribuem recursos de forma exatamente igual em todas as circunstâncias.","explanation":"Universalidade de cobertura não impõe idêntica aplicação de recursos.","sourceType":"AUTORAL","verified":"revisão técnica inicial","level":"conceitual"}],"sources":[["Edital CGU 2026","https://www.cebraspe.org.br/concursos/cgu_26_affc","Fonte primária: consulte edital e retificações."],["CGU 2022 — prova TI FGV","https://conhecimento.fgv.br/sites/default/files/concursos/cgu_2021_auditor_federal_de_financas_e_controle_-_area_tecnologia_da_informacaoaffc-ti_tipo_1_tarde.pdf","Prova oficial FGV; formato diferente de 2026."],["CGU 2022 — prova geral FGV","https://conhecimento.fgv.br/sites/default/files/concursos/cgu_2021_auditor_federal_de_financas_e_controleaffc_tipo_1_manha.pdf","Prova oficial FGV."],["CGU 2022 — gabarito definitivo","https://conhecimento.fgv.br/sites/default/files/concursos/cgu2021_gabarito_definitivo_retificado_20.04.2022.pdf","Conferir tipo da prova e anulações."],["TCU 2026 — auditoria TI","https://arquivos.qconcursos.com/prova/arquivo_prova/146630/cespe-cebraspe-2026-tcu-auditor-federal-de-controle-externo-area-de-controle-externo-orientacao-auditoria-de-tecnologia-da-informacao-prova.pdf","Caderno de prova disponibilizado por banco de questões."],["TCU 2026 — gabarito definitivo","https://cdn.cebraspe.org.br/concursos/tcu_25_aufc/arquivos/D599023DB31F3467DB9CC03BE3D58BFE91CD7351624DDF045C0FDB71B3569A51.pdf","Gabarito Cebraspe. Atenção a itens anulados."],["TCDF 2024 — questões infraestrutura","https://www.qconcursos.com/questoes-de-concursos/provas/cespe-cebraspe-2024-tc-df-auditor-de-controle-externo-area-especializada-especialidade-tecnologia-da-informacao-orientacao-microinformatica-de-ti/questoes","Banco de questões externo; acesso pode ser limitado."],["TCDF 2024 — gabarito definitivo","https://cdn.cebraspe.org.br/concursos/tc_df_24_auditor/arquivos/GAB_DEFINITIVO_012_TCDF_AUDITOR_003_01.PDF","Confira códigos, anulações e alterações."],["TCDF 2024 — discursiva oficial","https://cdn.cebraspe.org.br/concursos/TC_DF_24_AUDITOR/arquivos/PADRO_DEFINITIVO_DE_RESPOSTAS___PROVA_DISCURSIVA__ESPECIALIDADE_3.PDF","Padrão de resposta oficial."],["STJ 2024 — questões suporte","https://www.qconcursos.com/questoes-de-concursos/provas/cespe-cebraspe-2024-stj-analista-judiciario-area-apoio-especializado-especialidade-suporte-em-tecnologia-da-informacao/questoes?page=4","Banco de questões externo."],["STJ 2024 — padrão discursiva","https://cdn.cebraspe.org.br/concursos/stj_24/arquivos/PADRO_DEFINITIVO_DE_RESPOSTA___CARGO_18.PDF","Padrão oficial Cebraspe."],["TCE-AC 2024 — infraestrutura","https://www.qconcursos.com/questoes-de-concursos/provas/cespe-cebraspe-2024-tce-ac-analista-de-tecnologia-da-informacao-area-infraestrutura-de-ti","Banco de questões externo."],["CGU — PAINT/RAINT","https://www.gov.br/cgu/pt-br/assuntos/auditoria-e-fiscalizacao/PAINT-e-RAINT/Paint-e-Raint/","Referência institucional para auditoria orientada a risco."],["CGU — legislação da auditoria","https://www.gov.br/cgu/pt-br/assuntos/auditoria-e-fiscalizacao/legislacao","Fontes normativas oficiais."],["Pesquisa — revisão espaçada","https://doi.org/10.1038/s44159-022-00089-1","Revisão científica de estudo com espaçamento e recuperação."],["Pesquisa — prática intercalada","https://pubmed.ncbi.nlm.nih.gov/35436145/","Evidência sobre revisão intercalada."]],"disc":[{"title":"Incidente de ransomware em ambiente híbrido","prompt":"A CGU opera serviços críticos em infraestrutura híbrida. Após comprometimento de credencial privilegiada, parte dos backups torna-se indisponível. Em texto objetivo, apresente prioridades de contenção, preservação de evidências, recuperação e melhoria de controles.","checks":["Isolar e conter sem destruir evidências","Revogar credenciais e identificar alcance","RTO e RPO e testes de restauração","Comunicação e rastreabilidade","Recomendações proporcionais e governança"]},{"title":"Plano de migração e contratação de nuvem","prompt":"Uma unidade pretende migrar sistema legado e contratar serviço de nuvem. Produza uma nota técnica breve com análise de riscos, alternativas, continuidade, responsabilidades e fiscalização.","checks":["Necessidade e alternativas no ETP","Responsabilidade compartilhada","Critérios de segurança, SLA e métricas","Custo total e dependência de fornecedor","Estratégia de saída, portabilidade e aceite"]},{"title":"Auditoria de observabilidade e disponibilidade","prompt":"Em uma auditoria da disponibilidade de serviço digital, encontram-se dashboards incompletos e ausência de análise de causa-raiz. Esboce achado de auditoria e recomendações.","checks":["Critério, condição, causa e efeito","Confiabilidade e suficiência da evidência","SLI/SLO e monitoramento distribuído","Recomendações mensuráveis e responsabilidade da gestão","Plano de monitoramento dos resultados"]},{"title":"Identidade, Zero Trust e privilégios","prompt":"Após identificar contas de serviço com permissões excessivas e MFA incompleto, explique um plano de mitigação e os critérios para acompanhar sua efetividade.","checks":["Menor privilégio","MFA e controle de contas privilegiadas","Inventário e identidade de serviços","Auditoria de logs","Indicadores e reavaliação contínua"]}]};
